{
  "name": "turborepo-basic-shared",
  "version": "0.0.0",
  "private": true,
  "workspaces": [
    "apps/*",
    "packages/*"
  ],
  "scripts": {
    "prepare": "husky install",
    "postinstall": "manypkg check && yarn p prisma:generate",
    "release": "node ./scripts/release.js",
    "p": "yarn workspace @stately/prisma",
    "wc": "yarn workspace @stately/web-cypress",
    "web": "yarn workspace @stately/web",
    "docs": "yarn workspace @stately/docs",
    "lint": "turbo run lint",
    "test": "CI=true turbo run test"
  },
  "dependencies": {
    "@manypkg/cli": "^0.18.0",
    "husky": ">=6",
    "lint-staged": ">=10",
    "prettier": "^2.3.1",
    "turbo": "^1.2.9"
  },
  "lint-staged": {
    "*.{ts,tsx,js,jsx,json}": "prettier --write"
  },
  "engines": {
    "npm": ">=7.0.0",
    "node": ">=14.0.0"
  },
  "packageManager": "yarn@1.22.17"
}

{
  "name": "@stately/config",
  "version": "0.0.1",
  "main": "index.js",
  "license": "MIT",
  "files": [
    "eslint-preset.js"
  ],
  "scripts": {
    "lint": "echo \"No lint needed!\"",
    "test": "echo \"No test needed!\""
  },
  "dependencies": {
    "eslint-config-next": "^12.0.8",
    "eslint-config-prettier": "^8.3.0",
    "eslint-plugin-react": "7.28.0"
  }
}

{
  "name": "@stately/web-cypress",
  "version": "0.1.0",
  "main": "index.js",
  "private": true,
  "scripts": {
    "lint": "tsc",
    "test": "echo \"No test needed!\"",
    "test:cypress": "start-server-and-test \"(cd ../../apps/web && next start)\" http://localhost:3000 \"cypress run\""
  },
  "dependencies": {
    "@stately/web": "*"
  },
  "devDependencies": {
    "cypress": "^9.6.0",
    "start-server-and-test": "^1.14.0"
  }
}

{
  "name": "@stately/utils",
  "version": "0.1.0",
  "main": "src/index.ts",
  "private": true,
  "scripts": {
    "lint": "tsc",
    "test": "vitest"
  },
  "devDependencies": {
    "vitest": "^0.10.2"
  }
}

{
  "name": "@stately/tsconfig",
  "version": "0.0.1",
  "private": true,
  "main": "index.js",
  "files": [
    "base.json",
    "nextjs.json",
    "react-library.json"
  ],
  "scripts": {
    "lint": "echo \"No lint needed!\"",
    "test": "echo \"No test needed!\""
  }
}

{
  "name": "@stately/ui",
  "version": "0.0.1",
  "main": "./index.tsx",
  "types": "./index.tsx",
  "license": "MIT",
  "devDependencies": {
    "@stately/config": "*",
    "@stately/tsconfig": "*",
    "@types/react": "^17.0.37",
    "@types/react-dom": "^17.0.11",
    "typescript": "^4.5.3"
  },
  "scripts": {
    "lint": "tsc",
    "test": "echo \"No test needed!\""
  }
}

{
  "name": "@stately/prisma",
  "version": "0.1.0",
  "main": "src/index.ts",
  "private": true,
  "scripts": {
    "prisma:generate": "prisma generate",
    "lint": "tsc",
    "test": "echo \"No test needed!\""
  },
  "dependencies": {
    "@prisma/client": "^3.6.0"
  },
  "devDependencies": {
    "@types/node": "^17.0.12",
    "prisma": "^3.6.0"
  }
}

{
  "extends": "@stately/tsconfig/nextjs.json",
  "include": [
    "next-env.d.ts",
    "**/*.ts",
    "**/*.tsx"
  ],
  "exclude": [
    "node_modules"
  ]
}

const withTM = require("next-transpile-modules")(["@stately/ui"]);

module.exports = withTM({
  reactStrictMode: true,
});

/// <reference types="next" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/basic-features/typescript for more information.

import { Button } from "@stately/ui";

export default function Docs() {
  return (
    <div>
      <h1>Docs</h1>
      <Button />
    </div>
  );
}

import { describe, expect, it } from "vitest";
import { add } from "../utils";

describe("add", () => {
  it("should add two numbers", () => {
    expect(add(1, 2)).toEqual(3);
  });
});

