  it("Should have a button named 'Boop'", () => {
    cy.visit("/");

    cy.get("button").should("have.text", "Boop");
  });

  it("Should have a header named 'Web'", () => {
    cy.visit("/");

    cy.get("h1").should("have.text", "Web");
  });
});

